import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/booker-rivalry-list.B58OJFmF.js";var i=JSON.parse(`{"title":"Manage Rivalries","description":"","frontmatter":{},"headers":[],"relativePath":"guide/manage-rivalries.md","filePath":"guide/manage-rivalries.md"}`),a={name:`guide/manage-rivalries.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="manage-rivalries" tabindex="-1">Manage Rivalries <a class="header-anchor" href="#manage-rivalries" aria-label="Permalink to &quot;Manage Rivalries&quot;">​</a></h1><p>A booker&#39;s guide to rivalries — the feuds that give your shows a reason to exist. Rivalries build heat as wrestlers cross paths, force themselves onto your cards, and resolve in big matches.</p><p><strong>How heat works</strong> (the ATW RPG rules, applied automatically):</p><ul><li><strong>10 heat</strong> — they <em>must</em> wrestle at the next show. The game flags the match as must-book.</li><li><strong>20 heat</strong> — the rivalry can start ending: each show rolls to resolve it.</li><li><strong>30 heat</strong> — the feud is forced into a <strong>stipulation match</strong> (steel cage, hardcore, …) — the blowoff.</li></ul><hr><h2 id="step-1-—-create-a-rivalry" tabindex="-1">Step 1 — Create a rivalry <a class="header-anchor" href="#step-1-—-create-a-rivalry" aria-label="Permalink to &quot;Step 1 — Create a rivalry&quot;">​</a></h2><p>Open <strong>Rivalries</strong> from the navigation and click <strong>New Rivalry</strong>. Pick the two wrestlers and save — the rivalry starts at 0 heat and <strong>active</strong>.</p><p><img src="/screenshots/booker-rivalry-list.png" alt="Rivalry list"></p><p>You can&#39;t create a duplicate of a pair that&#39;s already active — one feud at a time per pairing.</p><hr><h2 id="step-2-—-let-heat-build-or-push-it-yourself" tabindex="-1">Step 2 — Let heat build (or push it yourself) <a class="header-anchor" href="#step-2-—-let-heat-build-or-push-it-yourself" aria-label="Permalink to &quot;Step 2 — Let heat build (or push it yourself)&quot;">​</a></h2><p>Heat rises on its own as the two wrestlers:</p><ul><li><strong>Face each other in matches</strong> — winners and losers both gain, scaled by match importance.</li><li><strong>Cut promos targeting each other</strong> — verbal jabs add heat without a physical contest.</li><li><strong>Interfere, get interfered on, or hit drama events</strong> — anything that throws them together.</li></ul><p>Every heat change is recorded as a <strong>heat event</strong> with a reason — open the rivalry&#39;s detail page to see the full history and understand why a feud escalated.</p><p><img src="/screenshots/booker-rivalry-detail.png" alt="Rivalry detail"></p><hr><h2 id="step-3-—-book-the-matches" tabindex="-1">Step 3 — Book the matches <a class="header-anchor" href="#step-3-—-book-the-matches" aria-label="Permalink to &quot;Step 3 — Book the matches&quot;">​</a></h2><p>The show-planning tools work the heat for you:</p><ul><li>The <strong>Add Segment</strong> dialog suggests your hottest unbooked rivalries (&quot;Suggested feuds (by heat)&quot;) so the must-book matches don&#39;t slip.</li><li>Card validation warns when two wrestlers with a hot rivalry are booked without a stipulation.</li><li>The <strong>Show Planning</strong> view flags shows that would leave a heat-10 rivalry unbooked.</li></ul><p><img src="/screenshots/booker-show-planning-must-book-warning.png" alt="Rivalry must-book warning"></p><hr><h2 id="step-4-—-let-it-resolve-or-cool-down" tabindex="-1">Step 4 — Let it resolve (or cool down) <a class="header-anchor" href="#step-4-—-let-it-resolve-or-cool-down" aria-label="Permalink to &quot;Step 4 — Let it resolve (or cool down)&quot;">​</a></h2><p>Two things end a rivalry:</p><ul><li><strong>Resolution matches</strong> — at 20+ heat, PLE matches between the two roll for resolution; a win ends the feud. On premium shows the threshold drops (rivalries are meant to blow off on the big stage), and a rivalry that keeps missing resolution attempts on PLEs is force-resolved to keep feuds from stalling.</li><li><strong>Heat decay</strong> — rivalries that stop being booked cool off gradually. If nothing re-ignites them, they fade to a natural end.</li></ul><p>Both are game-settings driven — admins tune the decay interval, decay amount, minimum resolution heat, and whether regular shows (vs PLEs only) can resolve feuds under <strong>Admin → Game Settings</strong>.</p><hr><h2 id="step-5-—-turn-a-rivalry-into-a-story-arc" tabindex="-1">Step 5 — Turn a rivalry into a story arc <a class="header-anchor" href="#step-5-—-turn-a-rivalry-into-a-story-arc" aria-label="Permalink to &quot;Step 5 — Turn a rivalry into a story arc&quot;">​</a></h2><p>From the rivalry&#39;s detail page, click <strong>Story Arc</strong> to launch the feud wizard — the structured, scripted way to run the feud (see <a href="./build-story-arcs.html">Build Story Arcs</a>). Rivalries handle the <em>heat</em>; story arcs handle the <em>script</em>.</p><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./book-your-first-show.html">Book Your First Show</a> — putting the feud on a card.</li><li><a href="./build-story-arcs.html">Build Story Arcs</a> — scripting the feud beat by beat.</li><li>The auto-generated <a href="./booker.html">Booker Overview</a> documents every rivalry screen.</li></ul>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};